#include "Kernel/NvmeMmioTransport.hpp"
#include <cstdio>
#include <cstring>
using namespace Davis;
int main(){alignas(4096) unsigned char mmio[0x3000]{};alignas(64) Nvme::IoCommand sq[64]{};alignas(64) Nvme::IoCompletion cq[64]{};NvmeMmioTransport::State s{};if(!NvmeMmioTransport::Bind(s,mmio,sq,cq,64,4,0))return 1;u64 cycles=0;for(u32 i=0;i<100000;i++){Nvme::IoCommand c{};c.opcode=6;c.cid=(u16)((i%65534)+1);if(!NvmeMmioTransport::Submit(&s,c))return 2;NvmeMmioTransport::Ring(&s,true,0);u16 slot=s.cqHead;cq[slot].cid=c.cid;cq[slot].status=(u16)(s.cqPhase?1:0);u16 st=0xffff;if(!NvmeMmioTransport::Poll(&s,c.cid,st)||((st>>1)!=0))return 3;NvmeMmioTransport::Ring(&s,false,0);cycles++;}if(s.submissions!=cycles||s.completions!=cycles||s.doorbellWrites!=cycles*2)return 4;*(u32*)(mmio+0x14)=1;NvmeMmioTransport::Reset(&s);if((*(u32*)(mmio+0x14)&1)||s.resets!=1)return 5;NvmeMmioTransport::State bad{};if(NvmeMmioTransport::Bind(bad,mmio,sq,cq,1,4,0)||NvmeMmioTransport::Bind(bad,mmio,sq,cq,64,3,0))return 6;std::printf("PASS nvme_mmio_transport cycles=%llu doorbells=%llu resets=%llu\n",(unsigned long long)cycles,(unsigned long long)s.doorbellWrites,(unsigned long long)s.resets);}
